                            (Z_to_bv 64 (SS + O + pt)) (Z_to_bv 64 nb) (Z_to_bv 64 64) (Z_to_bv 64 B) x25 x26 x28
                            (Z_to_bv 64 (64 - tl)) x30 x31).
